import { createServer } from 'node:http';
import { healthResponse } from '@demo-app/shared';

const SERVICE = 'notifications';
const VERSION = '0.1.0';
const PORT = Number(process.env.PORT ?? 4003);
const BROKER_URL = process.env.BROKER_URL ?? 'nats://localhost:4222';

const server = createServer((req, res) => {
  const url = req.url ?? '/';

  if (url === '/health' || url === '/ready') {
    res.writeHead(200, { 'content-type': 'application/json' });
    res.end(JSON.stringify(healthResponse(SERVICE, VERSION)));
    return;
  }

  if (url === '/' || url === '/notifications') {
    res.writeHead(200, { 'content-type': 'application/json' });
    res.end(
      JSON.stringify({
        service: SERVICE,
        version: VERSION,
        message: 'notifications service is up',
      })
    );
    return;
  }

  res.writeHead(404, { 'content-type': 'application/json' });
  res.end(JSON.stringify({ error: 'not found' }));
});

server.listen(PORT, () => {
  console.log('[' + SERVICE + '] listening on http://localhost:' + PORT);
  console.log('[' + SERVICE + '] broker ' + BROKER_URL);
});

